/**
 * SmartCare Database Types
 *
 * This file will eventually be auto-generated by the Supabase CLI:
 *   npx supabase gen types typescript --project-id <project-id> \
 *     --schema public > src/types/database.ts
 *
 * For now it is hand-written to match the Phase 1 Step 2 foundation schema
 * (migrations 001–003). Update this file after each migration is applied.
 *
 * ─── Naming conventions ───────────────────────────────────────────────────
 *   Row    → shape returned by SELECT
 *   Insert → shape required for INSERT (id/timestamps optional where defaulted)
 *   Update → Partial<Omit<Insert, immutable_fields>>
 *
 * ─── Changes in Phase 1 Step 2 ───────────────────────────────────────────
 *   - Renamed: doctor_profiles → doctors (matches real table name)
 *   - Fixed:   initiated_by is nullable (ON DELETE SET NULL on FK)
 *   - Removed: patient_profiles and audit_logs from Database.Tables
 *              (deferred — Phase 3). TypeScript types kept as placeholders
 *              for future use but not wired into the Database generic yet.
 *   - Added:   get_user_role and has_active_relationship to Functions
 */

// ─────────────────────────────────────────────────────────────────────────────
// Enums  (mirror PostgreSQL native enums created in 001_foundation_schema.sql)
// ─────────────────────────────────────────────────────────────────────────────

export type UserRole = "patient" | "doctor" | "admin";

export type Gender =
  | "male"
  | "female"
  | "other"
  | "prefer_not_to_say";

export type RelationshipStatus =
  | "pending"
  | "active"
  | "inactive"
  | "revoked"
  | "rejected";

export type InitiatorRole = "doctor" | "patient";

/**
 * Record types for medical records (Phase 2 Step 3)
 */
export type RecordType = "clinical_note" | "lab_result" | "prescription" | "imaging" | "other";

/**
 * Appointment status (Phase 3 Step 1)
 */
export type AppointmentStatus = "pending" | "confirmed" | "completed" | "cancelled" | "rejected";

/**
 * Prescription status (Phase 3 Step 2)
 */
export type PrescriptionStatus = "active" | "completed" | "discontinued";

/**
 * Admin Verification Status (Phase 7)
 */
export type DoctorVerificationStatus = "pending" | "approved" | "rejected";

// Deferred with patient_profiles (Phase 3) — kept here for future use
export type BloodType =
  | "A+"
  | "A-"
  | "B+"
  | "B-"
  | "AB+"
  | "AB-"
  | "O+"
  | "O-";

// ─────────────────────────────────────────────────────────────────────────────
// Table: profiles
// ─────────────────────────────────────────────────────────────────────────────

export interface ProfileRow {
  /** UUID — equals auth.users.id (1:1) */
  id: string;
  role: UserRole;
  full_name: string;
  avatar_url: string | null;
  phone: string | null;
  /** ISO 8601 date string (e.g. "1990-06-15") */
  date_of_birth: string | null;
  gender: Gender | null;
  is_active: boolean;
  notification_preferences: { email: boolean; in_app: boolean };
  created_at: string;
  updated_at: string;
}

export interface ProfileInsert {
  /** Must equal the auth.users.id — assigned by Supabase Auth, not generated */
  id: string;
  role?: UserRole;
  full_name: string;
  avatar_url?: string | null;
  phone?: string | null;
  date_of_birth?: string | null;
  gender?: Gender | null;
  is_active?: boolean;
  notification_preferences?: { email: boolean; in_app: boolean };
}

/** Supabase strictly typed Update requires Partial of the Row */
export type ProfileUpdate = Partial<ProfileRow>;
// role is excluded: role changes require the admin service-role client

// ─────────────────────────────────────────────────────────────────────────────
// Table: doctors  (was "doctor_profiles" — renamed to match real table)
// ─────────────────────────────────────────────────────────────────────────────

export interface DoctorRow {
  /** Generated UUID */
  id: string;
  /** FK → profiles(id) — the doctor's profile */
  profile_id: string;
  license_number: string;
  specialty: string;
  department: string | null;
  years_of_experience: number | null;
  bio: string | null;
  is_accepting_appointments: boolean;
  appointment_duration: number;
  clinic_name: string | null;
  clinic_address: string | null;
  /** Only admin can set this to true */
  is_verified: boolean;
  verification_status: DoctorVerificationStatus;
  rejection_reason: string | null;
  rejected_at: string | null;
  rejected_by: string | null;
  /** FK → profiles(id) — the admin who verified; null if admin deleted */
  verified_by: string | null;
  verified_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface DoctorInsert {
  profile_id: string;
  license_number: string;
  specialty: string;
  department?: string | null;
  years_of_experience?: number | null;
  bio?: string | null;
  is_accepting_appointments?: boolean;
  appointment_duration?: number;
  clinic_name?: string | null;
  clinic_address?: string | null;
  is_verified?: boolean;
  verification_status?: DoctorVerificationStatus;
  rejection_reason?: string | null;
  rejected_at?: string | null;
  rejected_by?: string | null;
  verified_by?: string | null;
  verified_at?: string | null;
}

/** Supabase strictly typed Update requires Partial of the Row */
export type DoctorUpdate = Partial<DoctorRow>;

/** Admin-only update shape — used with service-role client */
export type DoctorAdminUpdate = Partial<
  Omit<DoctorInsert, "profile_id" | "license_number">
>;

// ─────────────────────────────────────────────────────────────────────────────
// Table: doctor_patient_relationships
// ─────────────────────────────────────────────────────────────────────────────

export interface DoctorPatientRelationshipRow {
  /** Generated UUID */
  id: string;
  /** FK → profiles(id); role must be 'doctor' */
  doctor_id: string;
  /** FK → profiles(id); role must be 'patient' */
  patient_id: string;
  status: RelationshipStatus;
  /** FK → profiles(id); nullable — SET NULL if initiator's profile is deleted */
  initiated_by: string | null;
  initiator_role: InitiatorRole;
  /** Set by trigger when status transitions TO 'active' */
  established_at: string | null;
  /** Set by trigger when status transitions TO 'revoked' */
  revoked_at: string | null;
  /** FK → profiles(id); nullable */
  revoked_by: string | null;
  notes: string | null;
  created_at: string;
  updated_at: string;
}

export interface DoctorPatientRelationshipInsert {
  doctor_id: string;
  patient_id: string;
  /** Always 'pending' on insert — enforced by RLS WITH CHECK */
  status?: "pending";
  initiated_by: string;
  initiator_role: InitiatorRole;
  notes?: string | null;
}

/** Supabase strictly typed Update requires Partial of the Row */
export type DoctorPatientRelationshipUpdate = Partial<DoctorPatientRelationshipRow>;

