// ─────────────────────────────────────────────────────────────────────────────
// Database — generic type for createClient<Database>(...)
// Reflects only the tables that exist in the current schema (Phase 1 Step 2).
// ─────────────────────────────────────────────────────────────────────────────

export interface Database {
  public: {
    Tables: {
      profiles: {
        Row: ProfileRow;
        Insert: ProfileInsert;
        Update: ProfileUpdate;
        Relationships: unknown[];
      };
      doctors: {
        Row: DoctorRow;
        Insert: DoctorInsert;
        Update: DoctorUpdate;
        Relationships: unknown[];
      };
      doctor_patient_relationships: {
        Row: DoctorPatientRelationshipRow;
        Insert: DoctorPatientRelationshipInsert;
        Update: DoctorPatientRelationshipUpdate;
        Relationships: unknown[];
      };
      medical_records: {
        Row: MedicalRecordRow;
        Insert: MedicalRecordInsert;
        Update: MedicalRecordUpdate;
        Relationships: [
          {
            foreignKeyName: "medical_records_patient_id_fkey";
            columns: ["patient_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          },
          {
            foreignKeyName: "medical_records_doctor_id_fkey";
            columns: ["doctor_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          }
        ];
      };
      appointments: {
        Row: AppointmentRow;
        Insert: AppointmentInsert;
        Update: AppointmentUpdate;
        Relationships: [
          {
            foreignKeyName: "appointments_patient_id_fkey";
            columns: ["patient_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          },
          {
            foreignKeyName: "appointments_doctor_id_fkey";
            columns: ["doctor_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          }
        ];
      };
      prescriptions: {
        Row: PrescriptionRow;
        Insert: PrescriptionInsert;
        Update: PrescriptionUpdate;
        Relationships: [
          {
            foreignKeyName: "prescriptions_patient_id_fkey";
            columns: ["patient_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          },
          {
            foreignKeyName: "prescriptions_doctor_id_fkey";
            columns: ["doctor_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          }
        ];
      };
      consultation_notes: {
        Row: ConsultationNoteRow;
        Insert: ConsultationNoteInsert;
        Update: ConsultationNoteUpdate;
        Relationships: [
          {
            foreignKeyName: "consultation_notes_appointment_id_fkey";
            columns: ["appointment_id"];
            isOneToOne: true;
            referencedRelation: "appointments";
            referencedColumns: ["id"];
          },
          {
            foreignKeyName: "consultation_notes_patient_id_fkey";
            columns: ["patient_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          },
          {
            foreignKeyName: "consultation_notes_doctor_id_fkey";
            columns: ["doctor_id"];
            isOneToOne: false;
            referencedRelation: "profiles";
            referencedColumns: ["id"];
          }
        ];
      };
    };
    Views: Record<string, never>;
    Functions: {
      get_user_role: {
        Args: Record<string, never>;
        Returns: UserRole;
      };
      has_active_relationship: {
        Args: { p_doctor_id: string; p_patient_id: string };
        Returns: boolean;
      };
    };
    Enums: {
      user_role: UserRole;
      gender: Gender;
      relationship_status: RelationshipStatus;
      initiator_role: InitiatorRole;
      appointment_status: AppointmentStatus;
      prescription_status: PrescriptionStatus;
    };
  };
}
